#!/usr/bin/env node
/**
 * Add CSP hashes for generated inline JSON-LD blocks to dist/_headers.
 *
 * The public site deliberately disallows arbitrary inline JavaScript. Search
 * engines still expect structured data in inline application/ld+json blocks,
 * so each production build allowlists the exact generated bytes without
 * weakening script-src with unsafe-inline.
 */
import { createHash } from 'node:crypto';
import { promises as fs } from 'node:fs';
import path from 'node:path';

const DIST = path.resolve('dist');
const HEADERS = path.join(DIST, '_headers');
const JSON_LD_RE = /<script\b(?=[^>]*\btype=(?:"application\/ld\+json"|'application\/ld\+json'))[^>]*>([\s\S]*?)<\/script>/gi;

async function* files(dir) {
  for (const entry of await fs.readdir(dir, { withFileTypes: true })) {
    const target = path.join(dir, entry.name);
    if (entry.isDirectory()) yield* files(target);
    else yield target;
  }
}

const hashes = new Set();
for await (const file of files(DIST)) {
  if (!file.endsWith('.html')) continue;
  const html = await fs.readFile(file, 'utf8');
  for (const match of html.matchAll(JSON_LD_RE)) {
    const digest = createHash('sha256').update(match[1], 'utf8').digest('base64');
    hashes.add(`'sha256-${digest}'`);
  }
}

if (hashes.size === 0) throw new Error('add-csp-hashes: no JSON-LD blocks found');
let headers = await fs.readFile(HEADERS, 'utf8');
const marker = "script-src 'self' https://challenges.cloudflare.com";
if (!headers.includes(marker)) throw new Error('add-csp-hashes: public script-src marker not found');
headers = headers.replace(marker, `${marker} ${[...hashes].sort().join(' ')}`);
await fs.writeFile(HEADERS, headers);
console.log(`add-csp-hashes: allowlisted ${hashes.size} generated JSON-LD blocks in dist/_headers`);
